(x, y, t) => {
  const wx = Math.sin(x*0.018+t*0.35)*18 + Math.cos(y*0.013-t*0.22)*12 + Math.sin((x+y)*0.008+t*0.15)*8;
  const wy = Math.cos(y*0.02-t*0.28)*16 + Math.sin(x*0.016+t*0.32)*11 + Math.cos((x-y)*0.009-t*0.18)*7;
  const sx = x+wx, sy = y+wy;
  const src = [
    [140+Math.sin(t*0.55)*90, 60+Math.cos(t*0.4)*40, 0.085, 2.1],
    [340+Math.cos(t*0.48)*80, 170+Math.sin(t*0.65)*50, 0.095, 1.8],
    [240+Math.sin(t*0.32+2)*130, 110+Math.cos(t*0.5+1)*80, 0.065, 2.4],
    [80+Math.cos(t*0.75+1)*70, 190+Math.sin(t*0.58+3)*55, 0.11, 1.6],
    [380+Math.sin(t*0.42+4)*85, 50+Math.cos(t*0.85+2)*65, 0.075, 2.7],
    [200+Math.cos(t*0.38+5)*110, 210+Math.sin(t*0.52)*70, 0.088, 2.0],
    [300+Math.sin(t*0.6+1.5)*60, 90+Math.cos(t*0.7+0.5)*45, 0.1, 1.9],
    [60+Math.cos(t*0.45+3)*50, 130+Math.sin(t*0.55+2)*35, 0.12, 2.2]
  ];
  let aS=0, iS=0, eFlow=0;
  for (const [sX,sY,f,sp] of src) {
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const w=Math.sin(d*f-t*sp);
    aS+=w; iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5);
    eFlow+=Math.sin(d*0.03+t*0.8)*Math.cos(Math.atan2(sy-sY,sx-sX)*2+t*0.5)*0.15;
  }
  const act=aS/8, inh=iS/8;
  const bg=(Math.sin(sx*0.042+sy*0.028+t*0.85)+Math.sin(sx*0.033-sy*0.042+t*1.15))/2
    +Math.sin((sx+sy)*0.13+t*2.6)*0.2+Math.sin((sx-sy)*0.11-t*2.1)*0.2;
  const cx=240, cy=120, dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.055-ang*3.5-t*1.6)+Math.sin(dist*0.045+ang*4.5-t*1.3))*0.4;
  const grav=Math.sin(dist*0.025-t*0.9)*0.3/(1+dist*0.005);
  const photo=Math.sin(sx*0.08+sy*0.06+t*1.2)*Math.cos(sx*0.05-sy*0.07+t*0.8)*0.25;
  const reaction=Math.tanh((act-inh*0.65+bg*0.3+spiral+grav+photo+eFlow)*2.5);
  const cell=Math.tanh((Math.sin(sx*0.16)*Math.sin(sy*0.16)+Math.sin((sx+sy)*0.11+t)*0.5)*1.6)*0.3;
  const gridX=Math.abs(Math.sin(sx*0.25))*0.06, gridY=Math.abs(Math.sin(sy*0.25))*0.06;
  const grid=(gridX+gridY)*Math.max(0,1-Math.abs(reaction)*0.8);
  const scan=Math.sin(y*1.5+t*3)*0.015+0.985;
  const hBar=Math.max(0,1-Math.abs(y-30)*0.15)*Math.max(0,Math.sin(x*0.08+t*0.6)*0.5+0.5)*0.15;
  const hBar2=Math.max(0,1-Math.abs(y-210)*0.2)*Math.max(0,Math.sin(x*0.06+t*0.4+1)*0.5+0.5)*0.12;
  const vBar=Math.max(0,1-Math.abs(x-20)*0.3)*Math.max(0,Math.sin(y*0.1+t*0.7)*0.5+0.5)*0.1;
  const vBar2=Math.max(0,1-Math.abs(x-460)*0.25)*Math.max(0,Math.sin(y*0.08+t*0.5+2)*0.5+0.5)*0.08;
  const dotMatrix=Math.sin(sx*0.5)*Math.sin(sy*0.5)>0.7?0.08:0;
  const blend=reaction*0.65+cell*0.2+grid*0.08+(hBar+hBar2+vBar+vBar2)*0.5+dotMatrix*0.3;
  const v=blend*0.5+0.5;
  const pal=[[5,5,25],[15,10,80],[0,180,255],[0,255,180],[180,255,0],[255,220,0],[255,80,120],[255,0,200],[120,0,180],[5,5,25]];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=(0.85+Math.sin(reaction*Math.PI)*0.3)*scan;
  const neon=Math.abs(reaction)>0.65?1.35:Math.abs(reaction)>0.4?1.1:1.0;
  const glow=Math.max(0,1-dist*0.004)*0.15+0.85;
  const m=lum*neon*glow;
  return [
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*m+Math.max(0,reaction)*40)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*m+Math.max(0,photo)*30)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*m+Math.max(0,eFlow)*25)|0)
  ];
}
